// Zeroed at runtime; saves executable file size

// Global variable (no explicit init)
int bss_counter;

// Static global array (large, efficient storage)
static float large_buffer[20000];

// Static constant pointer (implicitly initialized to NULL)
static const char* error_msg;

void process_data() {
    // Static local variable
    static long internal_sum;
}
